import {
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  MeshPhysicalNodeMaterial
} from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  atan2,
  mix,
  smoothstep,
  radialGradient,
  positionWorld,
  timerLocal,
  uniform
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, RingGeometry, SphereGeometry, CylinderGeometry, PointLight, DirectionalLight, Vector3 } = ctx.THREE;

  const container = new Group();

  const activeTimelines = [];
  const activePrimitives = [];

  // Trackers for objects to animate manually
  let primaryGear = null;
  let secondaryGear = null;

  // 1. BACKDROP ZONE (Stage building)
  const backdropGeo = new PlaneGeometry(7.0, 6.0);
  const backdropMat = new MeshBasicNodeMaterial();

  // Radial gradient using three/tsl
  const radialUv = uv().sub(0.5);
  const dist = radialUv.length();
  const bgGrad = mix(
    vec3(0.043, 0.043, 0.063), // #0b0b10
    vec3(0.086, 0.086, 0.114), // #16161d
    smoothstep(0.0, 0.8, dist)
  );
  backdropMat.colorNode = bgGrad;

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  container.add(backdrop);

  // Contact shadow
  const shadowGeo = new PlaneGeometry(2.6, 1.2);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    alphaWrite: false,
    depthWrite: false
  });
  // Use TSL to generate radial soft ellipse shadow
  const shadowUv = uv().sub(0.5);
  const shadowDist = shadowUv.mul(vec2(1.0, 2.16)).length();
  const shadowAlpha = mix(0.5, 0.0, smoothstep(0.0, 0.5, shadowDist));
  shadowMat.colorNode = vec3(0, 0, 0);
  shadowMat.opacityNode = uniform(shadowAlpha);

  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.position.set(0, -1.2, -0.4);
  contactShadow.rotation.x = -Math.PI / 2;
  container.add(contactShadow);

  // 2. ORRERY MECHANISM SUBJECT
  const gearGroup = new Group();
  container.add(gearGroup);

  // Shared machined steel material
  const steelMat = new MeshPhysicalNodeMaterial({
    color: 0xe8ecf2,
    roughness: 0.5,
    metalness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
    anisotropy: 0.7
  });

  // Load physical model assets
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      // Find the main model gear inside the loaded GLTF scene
      let baseMesh = null;
      gltf.scene.traverse((child) => {
        if (child.isMesh && !baseMesh) {
          baseMesh = child;
        }
      });

      if (baseMesh) {
        // Primary gear logic
        primaryGear = baseMesh.clone();
        primaryGear.geometry.computeBoundingBox();
        const box = primaryGear.geometry.boundingBox;
        const width = box.max.x - box.min.x;
        const scaleFit = 1.6 / (width || 1.6);
        primaryGear.scale.set(scaleFit, scaleFit, scaleFit);
        primaryGear.material = steelMat;
        primaryGear.position.set(0, 0, 0);
        gearGroup.add(primaryGear);

        // Secondary small gear instance
        secondaryGear = baseMesh.clone();
        const smallScale = scaleFit * (0.9 / 1.6);
        secondaryGear.scale.set(smallScale, smallScale, smallScale);
        secondaryGear.material = steelMat;

        // Tooth alignment position and phase mesh lock
        secondaryGear.position.set(1.15, 0.35, -0.1);
        // Correct starting offset orientation to prevent initial tooth intersection
        secondaryGear.rotation.z = 2.45; 

        gearGroup.add(secondaryGear);
      }
    }).catch(err => {
      console.warn("Failed to load mesh asset for Orrery:", err);
    });
  }

  // Jewel pivot sphere (at primary hub center)
  const jewelGeo = new SphereGeometry(0.12, 32, 24);
  const jewelMat = new MeshPhysicalMaterial({
    color: 0xff2a38,
    transmission: 0.6,
    ior: 1.76,
    roughness: 0.1,
    thickness: 0.2,
    emissive: 0xff2a38,
    emissiveIntensity: 1.8
  });
  const jewelPivot = new Mesh(jewelGeo, jewelMat);
  jewelPivot.position.set(0, 0, 0.05);
  gearGroup.add(jewelPivot);

  // Arbor shafts (ink cylinders running through both gear center hubs)
  const shaftGeo = new CylinderGeometry(0.05, 0.05, 0.8, 16);
  const shaftMat = new MeshStandardNodeMaterial({
    color: 0x16161d,
    roughness: 0.7,
    metalness: 0.2
  });

  const shaftPrimary = new Mesh(shaftGeo, shaftMat);
  shaftPrimary.rotation.x = Math.PI / 2;
  shaftPrimary.position.set(0, 0, -0.2);
  gearGroup.add(shaftPrimary);

  const shaftSecondary = new Mesh(shaftGeo, shaftMat);
  shaftSecondary.rotation.x = Math.PI / 2;
  shaftSecondary.position.set(1.15, 0.35, -0.3);
  gearGroup.add(shaftSecondary);

  // 3. LIGHTING RIG
  const localRig = new Group();

  // Strong directional key light (accenting the rims and spokes)
  const keyLight = new DirectionalLight(0xe8ecf2, 1.2);
  keyLight.position.set(3, 4, 3);
  localRig.add(keyLight);

  // Red accent back rim light
  const rimLight = new DirectionalLight(0xff2a38, 1.4);
  rimLight.position.set(-3, -2, -1.5);
  localRig.add(rimLight);

  const fillPoint = new PointLight(0xe8ecf2, 0.6, 12);
  fillPoint.position.set(-2, 3, 2);
  localRig.add(fillPoint);

  container.add(localRig);

  // 4. TYPOGRAPHY ZONE
  const typographyGroup = new Group();
  container.add(typographyGroup);

  // Baseline layout configs
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const headlineItem = items.find(i => i.role === 'headline' || i.text.length < 25);
  const captionItem = items.find(i => i.role === 'caption' || i.text.length >= 25);

  if (headlineItem) {
    const textH = ctx.fontAtlas.createText(headlineItem.text, {
      fontSize: 0.32,
      color: '#e8ecf2',
      align: 'center'
    });
    textH.position.set(0, -1.7, 0);
    typographyGroup.add(textH);
  }

  if (captionItem) {
    const textC = ctx.fontAtlas.createText(captionItem.text, {
      fontSize: 0.1,
      color: '#ff2a38',
      align: 'center',
      letterSpacingPx: 0.08
    });
    textC.position.set(0, -2.1, 0);
    typographyGroup.add(textC);
  }

  // 5. ANIMATION LAYER (Synchronous loops & transitions)
  const frameLoop = () => {
    // Constant meshing rotation of gears
    const timeSec = performance.now() * 0.001;
    if (primaryGear) {
      primaryGear.rotation.z = timeSec * 0.08;
    }
    if (secondaryGear) {
      // Mesh phase alignment: gear ratio 16:9, counter rotating
      secondaryGear.rotation.z = 2.45 - (timeSec * 0.142);
    }
    requestAnimationFrameId = requestAnimationFrame(frameLoop);
  };
  let requestAnimationFrameId = requestAnimationFrame(frameLoop);

  // Entrance settlement animations
  gsap.fromTo(gearGroup.position, 
    { y: -0.4, z: -1 }, 
    { y: 0, z: 0, duration: 1.2, ease: "power4.out" }
  );
  gsap.fromTo(typographyGroup.position, 
    { y: -0.15 }, 
    { y: 0, duration: 0.9, ease: "power3.out" }
  );

  // Apply visual cinematic primitives if designated
  if (config.cinematicPrimitives) {
    for (const primitive of config.cinematicPrimitives) {
      if (ctx.primitives[primitive.name]) {
        const primResult = ctx.primitives[primitive.name](container, primitive.params);
        if (primResult) {
          activePrimitives.push(primResult);
        }
      }
    }
  }

  // 6. RESOURCE CLEANUP
  container.userData.cleanup = function () {
    cancelAnimationFrame(requestAnimationFrameId);

    // Kill local gsap timelines
    activeTimelines.forEach(tl => tl.kill());

    // Clean cinematic primitives
    activePrimitives.forEach(p => {
      if (typeof p.cleanup === 'function') p.cleanup();
    });

    steelMat.dispose();
    jewelMat.dispose();
    shaftMat.dispose();
    shadowMat.dispose();
    backdropMat.dispose();
  };

  return container;
}
